    finally:
        if on_stage_finish:
            on_stage_finish("stage2", (time.perf_counter() - stage_started) * 1000, stage2_cached)

    stage3_system, stage3_template = load_prompt_parts("03_memory_use_guided_generation.txt")
    stage3_user = render_prompt(
        stage3_template,
        build_stage3_input(
